&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de paladin&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_paladin_0&quot; href=&quot;#Les_arch&#233;types_de_paladin_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-B&#233;ni-(Paladin).html&quot; title=&quot;Bouclier b&#233;ni&quot;&gt;Bouclier b&#233;ni&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Du-Temple-(Paladin).html&quot; title=&quot;Champion du temple&quot;&gt;Champion du temple&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Temp&#233;r&#233;-(Paladin).html&quot; title=&quot;Champion temp&#233;r&#233;&quot;&gt;Champion temp&#233;r&#233;&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Fant&#244;mes-(Paladin).html&quot; title=&quot;Chasseur de fant&#244;mes&quot;&gt;Chasseur de fant&#244;mes&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Divin-(Paladin).html&quot; title=&quot;Chasseur divin&quot;&gt;Chasseur divin&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Des-Pi&#232;ces-(Paladin).html&quot; title=&quot;Chevalier des pi&#232;ces&quot;&gt;Chevalier des pi&#232;ces&lt;/a&gt; (MM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Empyr&#233;en-(Paladin).html&quot; title=&quot;Chevalier empyr&#233;en&quot;&gt;Chevalier empyr&#233;en&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;tincelant-(Paladin).html&quot; title=&quot;Chevalier &#233;tincelant&quot;&gt;Chevalier &#233;tincelant&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Divin-(Paladin).html&quot; title=&quot;D&#233;fenseur divin&quot;&gt;D&#233;fenseur divin&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Elu-(Paladin).html&quot; title=&quot;&#201;lu&quot;&gt;&#201;lu&lt;/a&gt; &lt;i&gt;(FF)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Du-Courage-(Paladin).html&quot; title=&quot;&#201;p&#233;e du courage&quot;&gt;&#201;p&#233;e du courage&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;au-Des-Morts-Vivants-(Paladin).html&quot; title=&quot;Fl&#233;au des morts-vivants&quot;&gt;Fl&#233;au des morts-vivants&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glaive-De-Lesprit-(Paladin).html&quot; title=&quot;Glaive de l&amp;#39;esprit&quot;&gt;Glaive de l&#39;esprit&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-De-La-Lumi&#232;re-Sainte-(Paladin).html&quot; title=&quot;Guerrier de la lumi&#232;re sainte&quot;&gt;Guerrier de la lumi&#232;re sainte&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Saint-(Paladin).html&quot; title=&quot;Guide saint&quot;&gt;Guide saint&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hospitalier-(Paladin).html&quot; title=&quot;Hospitalier&quot;&gt;Hospitalier&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;L&#233;gat-(Paladin).html&quot; title=&quot;L&#233;gat&quot;&gt;L&#233;gat&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Asserment&#233;-(Paladin).html&quot; title=&quot;Paladin asserment&#233;&quot;&gt;Paladin asserment&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Gris-(Paladin).html&quot; title=&quot;Paladin gris&quot;&gt;Paladin gris&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;dempteur-(Paladin).html&quot; title=&quot;R&#233;dempteur&quot;&gt;R&#233;dempteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Gardien-(Paladin).html&quot; title=&quot;Sage gardien&quot;&gt;Sage gardien&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Pistolet-(Paladin).html&quot; title=&quot;Saint pistolet&quot;&gt;Saint pistolet&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Tacticien-(Paladin).html&quot; title=&quot;Saint tacticien&quot;&gt;Saint tacticien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-Pierre-(Paladin).html&quot; title=&quot;Seigneur de pierre&quot;&gt;Seigneur de pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serviteur-Sacr&#233;-(Paladin).html&quot; title=&quot;Serviteur sacr&#233;&quot;&gt;Serviteur sacr&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;L&#39;antipaladin&lt;/a&gt; (classe alternative) (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Du-S&#233;pulcre-(Paladin).html&quot; title=&quot;Chevalier du s&#233;pulcre&quot;&gt;Chevalier du s&#233;pulcre&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Insinuateur-(Paladin).html&quot; title=&quot;Insinuateur&quot;&gt;Insinuateur&lt;/a&gt; &lt;i&gt;(AoE)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saccageur-(Paladin).html&quot; title=&quot;Saccageur&quot;&gt;Saccageur&lt;/a&gt; &lt;i&gt;(ISC)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Semeur-De-Peur-(Antipaladin).html&quot; title=&quot;Semeur de peur&quot;&gt;Semeur de peur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html&quot; title=&quot;Gobelours&quot;&gt;Gobelours&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-(Antipaladin).html&quot; title=&quot;Tyran&quot;&gt;Tyran&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-De-Fer-(Antipaladin).html&quot; title=&quot;Tyran de fer&quot;&gt;Tyran de fer&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;i&gt;Entre le noble altruisme du paladin et la violence chaotique de l&#39;antipaladin, il existe un chemin d&#233;vou&#233; &#224; l&#39;ambition. Refusant les cha&#238;nes qui le rattacheraient &#224; une unique divinit&#233;, l&#39;insinuateur se lie &#224; n&#39;importe quelle cause pourvu qu&#39;elle l&#39;aide &#224; faire progresser ses propres int&#233;r&#234;ts, imitant ainsi les pouvoirs divins.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Cet arch&#233;type est seulement accessible &#224; la classe alternative d’&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;antipaladin&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Code de conduite &lt;a class=&quot;headeranchor&quot; id=&quot;Code_de_conduite_0&quot; href=&quot;#Code_de_conduite_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;L’insinuateur est obligatoirement &lt;a class=&quot;pagelink&quot; href=&quot;Alignement.html&quot; title=&quot;Mauvais&quot;&gt;mauvais&lt;/a&gt;. Il doit toujours oeuvrer pour son propre profit, sa gloire ou ses int&#233;r&#234;ts, et doit se soumettre au code de conduite des Ext&#233;rieurs qu&#39;il appelle &#224; chaque jour - voir le pouvoir d&#39;appel plus bas.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Appel (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Appel_Ext_1&quot; href=&quot;#Appel_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au d&#233;but de chaque jour, l&#39;insinuateur peut m&#233;diter pendant 10 minutes pour appeler et n&#233;gocier avec un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;Ext&#233;rieur&lt;/a&gt; afin d&#39;obtenir ses pouvoirs pour un jour. Un insinuateur peut invoquer librement un Ext&#233;rieur de son alignement, mais il peut aussi faire appel &#224; un Ext&#233;rieur dont l&#39;alignement diff&#232;re d&#39;une cat&#233;gorie par rapport au sien en r&#233;ussissant un test de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; de DD 15 + son niveau d&#39;insinuateur. Lorsqu&#39;il est li&#233; &#224; un Ext&#233;rieur, il &#233;mane de lui une aura correspondant aux alignements de l&#39;Ext&#233;rieur, et il devient vuln&#233;rable aux effets ciblant les cr&#233;atures poss&#233;dant son alignement. Aucun de ses pouvoirs magiques ou capacit&#233;s surnaturelles ne fonctionne s&#39;il n&#39;est pas li&#233; &#224; un Ext&#233;rieur. Ce pouvoir remplace l’&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADUMAL&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura du mal&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; D&#233;tection de l&#39;&#233;quilibre (Mag) &lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;tection_de_l&#233;quilibre_Mag_2&quot; href=&quot;#D&#233;tection_de_l&#233;quilibre_Mag_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un insinuateur peut d&#233;tecter si une personne est fortement align&#233;e avec le bien ou le mal &#224; volont&#233;. Ce pouvoir fonctionne comme la &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#DETECTIONDUBIEN&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;d&#233;tection du bien&lt;/a&gt; de l&#39;antipaladin et la remplace, mais elle d&#233;tecte seulement si la personne est neutre ou non vis &#224; vis du bien ou du mal, ainsi que la taille de son aura, et ne r&#233;v&#232;le pas son alignement..&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Ch&#226;timent de l&#39;impudence (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Ch&#226;timent_de_limpudence_Sur_3&quot; href=&quot;#Ch&#226;timent_de_limpudence_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une fois par jour, un insinuateur peut faire appel aux puissances qu&#39;il invoque pour &#233;craser leurs ennemis communs. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, l’insinuateur d&#233;signe un ennemi situ&#233; dans son champ de vision et le prend pour cible de son ch&#226;timent de l&#39;impudence. Si la cible ne partage aucun &lt;a class=&quot;pagelink&quot; href=&quot;Alignement.html&quot; title=&quot;L&amp;#39;alignement&quot;&gt;alignement&lt;/a&gt;  avec l&#39;Ext&#233;rieur qu&#39;il a appel&#233; aujourd&#39;hui, l’insinuateur ajoute son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; (s’il en a un) &#224; ses jets d’attaques et la moiti&#233; de son niveau d’insinuateur &#224; tous les jets de d&#233;g&#226;ts contre elle. Si la cible est un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;Ext&#233;rieur&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Dragon.html&quot; title=&quot;Les dragons v&#233;ritables&quot;&gt;dragon&lt;/a&gt; ou un individu poss&#233;dant des niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; poss&#233;dant un &lt;a class=&quot;pagelink&quot; href=&quot;Alignement.html&quot; title=&quot;L&amp;#39;alignement&quot;&gt;alignement&lt;/a&gt; oppos&#233; &#224; celui de l&#39;Ext&#233;rieur appel&#233;, le bonus aux d&#233;g&#226;ts passe &#224; 1 points de d&#233;g&#226;ts par niveau de l’insinuateur pour la premi&#232;re attaque r&#233;ussie. Dans tous les cas, les attaques du ch&#226;timent de l&#39;impudence ignorent toutes les &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;r&#233;ductions de d&#233;g&#226;ts&lt;/a&gt; dont la cible pourrait b&#233;n&#233;ficier.&lt;br /&gt;&lt;br /&gt;De plus, lorsqu’un ch&#226;timent de l&#39;impudence est en cours, l&#39;insinuateur gagne un nombre de points de vie temporaires &#233;gal &#224; son niveau d&#39;insinuateur.&lt;br /&gt;&lt;br /&gt;L’effet du ch&#226;timent persiste jusqu’&#224; ce que la cible soit morte ou jusqu’&#224; ce que l’insinuateur se repose et r&#233;cup&#232;re son quota quotidien d’utilisations de cette capacit&#233;. Au niveau 4 et tous les trois niveaux par la suite, l’insinuateur obtient une utilisation quotidienne suppl&#233;mentaire de ce pouvoir, comme indiqu&#233; sur la Table 2-13, avec un maximum de sept utilisations quotidiennes au niveau 19. &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CHATIMENTDUBIEN&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;ch&#226;timent du bien&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Gu&#233;rison &#233;go&#239;ste (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Gu&#233;rison_&#233;go&#239;ste_Sur_4&quot; href=&quot;#Gu&#233;rison_&#233;go&#239;ste_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; partir du niveau  2, un  insinuateur sait soigner ses propres blessures. Ce pouvoir fonctionne commme l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt; du paladin mais il ne peut l&#39;utiliser que sur lui-m&#234;me. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#TOUCHERDECORRUPTION&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;toucher de corruption&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Aura d&#39;&#233;go (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Aura_d&#233;go_Sur_5&quot; href=&quot;#Aura_d&#233;go_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Il &#233;mane d’un insinuateur de niveau  3 une aura de confiance qui impose &#224; tous les ennemis situ&#233;s dans un rayon de 3 m un malus de –2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;terreur&lt;/a&gt; et aux alli&#233;s un bonus de +2 contre ces m&#234;mes effets. Cette capacit&#233; fonctionne seulement lorsque l’insinuateur est conscient, mais pas s’il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Mort.html&quot; title=&quot;Mort&quot;&gt;mort&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADELACHETE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura de l&#226;chet&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Sant&#233; ent&#234;t&#233;e (Ext) &lt;a class=&quot;headeranchor&quot; id=&quot;Sant&#233;_ent&#234;t&#233;e_Ext_6&quot; href=&quot;#Sant&#233;_ent&#234;t&#233;e_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau  3,  l&#39;insinuateur subit seulement la moiti&#233; des &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissements temporaires&lt;/a&gt; inflig&#233;s par les effets de  &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;poison&quot;&gt;poison&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;maladie&quot;&gt;maladie&lt;/a&gt;, et ces afflictions ne peuvent pas abaisser ses caract&#233;ristiques en dessous de 1. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#VECTEURDEMALADIES&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;vecteur de maladies&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Cupidit&#233; (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Cupidit&#233;_Sur_7&quot; href=&quot;#Cupidit&#233;_Sur_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; partir du niveau  3, et &#224; tous les trois niveaux par la suite, un insinuateur sait gu&#233;rir ses propres maux. Ce pouvoir fonctionne commme les &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ces&lt;/a&gt; du paladin mais il ne peut l&#39;utiliser que sur lui-m&#234;me. Ce pouvoir remplace les &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CRUAUTE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;cruaut&#233;s&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Don suppl&#233;mentaire &lt;a class=&quot;headeranchor&quot; id=&quot;Don_suppl&#233;mentaire_8&quot; href=&quot;#Don_suppl&#233;mentaire_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; partir du niveau  4, et &#224; tous les trois niveaux par la suite, un insinuateur gagne un don suppl&#233;mentaire. Il doit s&#39;agir d&#39;un don de combat ou du don &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt;. Ce pouvoir remplace les sorts de l&#39;antipaladin.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Canalisation d’&#233;nergie (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Canalisation_d’&#233;nergie_Sur_9&quot; href=&quot;#Canalisation_d’&#233;nergie_Sur_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Lorsque l’insinuateur atteint le niveau  4, il acquiert la capacit&#233; surnaturelle de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html#CANALISATIONDENERGIE&quot; title=&quot;Le pr&#234;tre&quot;&gt;canaliser de l’&#233;nergie n&#233;gative&lt;/a&gt; avec un niveau effectif de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt; &#233;gal &#224; son niveau d’insinuateur. S&#39;il est li&#233; &#224; un Ext&#233;rieur neutre, il peut canaliser l&#39;&#233;nergie positive comme un pr&#234;tre de niveau &#233;gal &#224; la moiti&#233; de son niveau d&#39;insinuateur. Chaque canalisation d’&#233;nergie consomme deux utilisations de sa capacit&#233; de gu&#233;rison &#233;go&#239;ste. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CANALISATIONDENERGIENEGATIVE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;canalisaiton d&#39;&#233;nergie n&#233;gative&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Faveur de l&#39;ambition (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Faveur_de_lambition_Sur_10&quot; href=&quot;#Faveur_de_lambition_Sur_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Lorsque l&#39;insinuateur re&#231;oit la faveur des fi&#233;lons, s&#39;il a choisi d&#39;am&#233;liorer son arme, il peut lui conf&#233;rer les propri&#233;t&#233;s &lt;a class=&quot;unknownlink&quot; href=&quot;Impie.html&quot; title=&quot;Pathfinder-RPG.impie&quot;&gt;impie&lt;/a&gt;, &lt;a class=&quot;unknownlink&quot; href=&quot;Axiomatique.html&quot; title=&quot;Pathfinder-RPG.axiomatique&quot;&gt;axiomatique&lt;/a&gt; et &lt;a class=&quot;unknownlink&quot; href=&quot;Anarchique.html&quot; title=&quot;Pathfinder-RPG.anarchique&quot;&gt;anarchique&lt;/a&gt; uniquement s&#39;il est li&#233; &#224; un Ext&#233;rieur d&#39;alignement correspondant. S&#39;il choisit un serviteur, il change de serviteur &#224; chaque jour correspondant au nouvel alignement de son Ext&#233;rieur. Ce pouvoir modiifie  &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#FAVEURDESFIELONS&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;faveur des fi&#233;lons&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Aura d&#39;ambition (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Aura_dambition_Sur_11&quot; href=&quot;#Aura_dambition_Sur_11&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Il &#233;mane d’un insinuateur de niveau  8 une aura qui impose &#224; tous les ennemis situ&#233;s dans un rayon de 3 m un malus de –1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; et aux alli&#233;s un bonus de +1 &#224; ces m&#234;mes jets. Ces bonus ne se cumulent pas avec les autres auras. Cette capacit&#233; fonctionne seulement lorsque l’insinuateur est conscient, mais pas s’il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Mort.html&quot; title=&quot;Mort&quot;&gt;mort&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADEDESESPOIR&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura de d&#233;sespoir&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Aura de gloire (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Aura_de_gloire_Sur_12&quot; href=&quot;#Aura_de_gloire_Sur_12&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 11, un insinuateur peut sacrifier deux utilisations de sa capacit&#233; de ch&#226;timent de l&#39;impudence pour permettre &#224; tous ses alli&#233;s situ&#233;s &#224; 3 m ou moins d’utiliser un ch&#226;timent de l&#39;impudence avec ses propres bonus. Les alli&#233;s doivent utiliser ce ch&#226;timent de l&#39;impudence avant que le d&#233;but du prochain tour de l’insinuateur et les bonus persistent pendant 1 minute. Ce pouvoir s’utilise par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADEVENGEANCE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura de vengeance&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Aura de croyance (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Aura_de_croyance_Sur_13&quot; href=&quot;#Aura_de_croyance_Sur_13&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau  14, l&#39;insinuateur re&#231;oit le pouvoir d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADUPECHE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura du p&#233;ch&#233;&lt;/a&gt; de l&#39;antipaladin, mais ses armes sont consid&#233;r&#233;es comme Chaotiques ou Loyales s&#39;il invoque un Ext&#233;rieur Chaotique ou Loyal. Si l&#39;Ext&#233;rieur qu&#39;il invoque a plusieurs composantes d&#39;alignement, il choisit pendant les dix minutes de m&#233;ditation quelle composante il souhaite repr&#233;senter aujourd&#39;hui. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADUPECHE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura du p&#233;ch&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Aura d&#39;indomptabilit&#233; (Ext) &lt;a class=&quot;headeranchor&quot; id=&quot;Aura_dindomptabilit&#233;_Ext_14&quot; href=&quot;#Aura_dindomptabilit&#233;_Ext_14&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau  17, un insinuateur gagne une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/- s&#39;il invoque un Ext&#233;rieur Neutre pour la journ&#233;e. Sinon, il gagne une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 10 qui n&#39;est ignor&#233;e que par les alignements oppos&#233;s &#224; ceux de son Ext&#233;rieur li&#233;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADEDEPRAVATION&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura de d&#233;pravation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Champion personnel (Ext) &lt;a class=&quot;headeranchor&quot; id=&quot;Champion_personnel_Ext_15&quot; href=&quot;#Champion_personnel_Ext_15&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau  20, un insinuateur devient l&#39;avatar m&#234;me de ses d&#233;sirs &#233;go&#239;stes. Sa RD passe &#224; 15 (10 si l&#39;Ext&#233;rieur est Neutre) et il double les bonus conf&#233;r&#233;s &#224; ses jets d&#39;attaque et de d&#233;g&#226;ts par son ch&#226;timent de l&#39;impudence. De plus, il peut changer d&#39;Ext&#233;rieur librement en m&#233;ditant pendant 10 minutes. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CHAMPIONMAUDIT&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;champion maudit&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Anciens insinuateurs&lt;a class=&quot;headeranchor&quot; id=&quot;Anciens_insinuateurs_16&quot; href=&quot;#Anciens_insinuateurs_16&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Lorsqu’un insinuateur accomplit sciemment un acte altruiste, ou commet une violence qui n&#39;avance pas ses propres int&#233;r&#234;ts, il perd toutes ses capacit&#233;s d’insinuateur (y compris la faveur des fi&#233;lons mais pas la formation aux armes, armures et boucliers). Il ne peut plus gagner de niveaux d’insinuateur. Il r&#233;cup&#232;re ses capacit&#233;s et peut &#224; nouveau progresser en tant qu’insinuateur s’il fait p&#233;nitence pour ses erreurs (voir le sort de &lt;a class=&quot;pagelink&quot; href=&quot;P&#233;nitence.html&quot; title=&quot;P&#233;nitence&quot;&gt;p&#233;nitence&lt;/a&gt;). S&#39;il viole le code de conduite de son protecteur Ext&#233;rieur, il ne peut plus faire appel aux services d&#39;Ext&#233;rieurs de cet alignement &#224; moins d&#39;avoir fait p&#233;nitence aussi.
